package com.example.digitalnotam.scenario.rwylim;
import com.example.digitalnotam.baseline.BaselineRunwayCatalog;import com.example.digitalnotam.domain.*;import com.example.digitalnotam.workflow.DigitalNotamPipeline;import org.w3c.dom.Document;import java.time.Instant;import java.util.List;
public final class RwyLimScenarioBuilderTest {
 public static void main(String[]args)throws Exception{var catalog=new BaselineRunwayCatalog();var values=catalog.list("EADD",Instant.parse("2026-08-01T08:00:00Z"),Instant.parse("2026-08-02T18:00:00Z"));var runway=values.stream().filter(x->"09L/27R".equals(x.designator())).findFirst().orElseThrow();var r=new AdLimRestriction("RESERV","TAKEOFF","","","","","","","","","","","","","","","","","");Notam n=notam(runway.designator()).withAdLimRestrictions(List.of(r)).withRwyClsTarget("RUNWAY",runway.uuid(),"");Document d=new RwyLimScenarioBuilder().build(n);if(d.getElementsByTagNameNS("*","RunwayDirection").getLength()!=2)throw new AssertionError("full runway directions");new RwyLimNotamProducer().produce(d,n);text(d,"selectionCode","QMRLT");contains(d,"text","RWY 09L/27R CLOSED, EXCEPT FOR TKOF");validate(d);var serialize=DigitalNotamPipeline.class.getDeclaredMethod("serialize",Document.class);serialize.setAccessible(true);String c=new DigitalNotamPipeline().transform((String)serialize.invoke(null,d),"RWY.LIM");if(!c.contains("QMRLT")||!c.contains("RWY 09L/27R"))throw new AssertionError(c);var fato=values.stream().filter(x->"FATO".equals(x.type())).findFirst().orElseThrow();var complex=new AdLimRestriction("CONDITIONAL","ALL","OAT","IFR","HOSP","CIVIL","INTL","SCHEDULED","HELICOPTER","JET","12","M","AT_OR_BELOW","5","T","AT_OR_ABOVE","1","HR","CALL OPS");Notam fn=notam(fato.designator()).withAdLimRestrictions(List.of(complex)).withRwyClsTarget("RUNWAY",fato.uuid(),"");Document fd=new RwyLimScenarioBuilder().build(fn);new RwyLimNotamProducer().produce(fd,fn);text(fd,"selectionCode","QFPAP");contains(fd,"text","PPR 1 HR CALL OPS");validate(fd);System.out.println("RWY.LIM scenario tests passed");}
 private static Notam notam(String designator){return new Notam("rwylim-test","D9998/26","RWY.LIM","RUNWAY LIMITATION","EADD","RUNWAY","RWY "+designator+" LIMITED",designator,"","LIMITED","MAINT","NOTE","2026-08-01T08:00:00Z","2026-08-02T18:00:00Z","52.37166667","31.94944444","5","N","W","QMRLT","IV","NBO","A","","","CONTINUOUS","ANY","08:00","18:00","DRAFT","2026-07-23T00:00:00Z","2026-07-23T00:00:00Z");}
 private static void validate(Document d)throws Exception{var m=DigitalNotamPipeline.class.getDeclaredMethod("validateXsd",Document.class);m.setAccessible(true);m.invoke(null,d);}private static void text(Document d,String l,String e){var n=d.getElementsByTagNameNS("*",l);for(int i=0;i<n.getLength();i++)if(e.equals(n.item(i).getTextContent().trim()))return;throw new AssertionError(l);}private static void contains(Document d,String l,String e){var n=d.getElementsByTagNameNS("*",l);for(int i=0;i<n.getLength();i++)if(n.item(i).getTextContent().contains(e))return;throw new AssertionError(e);}
}
